def f(n):
    # count partitions into distinct parts
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def distinct(remaining, max_part):
        if remaining == 0:
            return 1
        if max_part == 0:
            return 0
        # either include max_part or skip it
        skip = distinct(remaining, max_part - 1)
        include = distinct(remaining - max_part, max_part - 1) if remaining >= max_part else 0
        return skip + include
    return distinct(n, n)

