    def mobius(k):
        if k == 1: return 1
        factors = []
        temp = k
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                factors.append(p)
                temp //= p
                if temp % p == 0:
                    return 0  # squared factor
            p += 1
        if temp > 1:
            factors.append(temp)
        return (-1) ** len(factors)
